    @Before
    public void setUp() {
        // Use spy to allow intercepting the protected _reportError method
        parserMinimalBase = spy(new TestParserMinimalBase());
    }

    @Test
    public void testReportOverflowLong_StandardInput() throws Exception {
        String numDesc = "9223372036854775808";

        // Access the protected method via reflection
        Method method = ParserMinimalBase.class.getDeclaredMethod("reportOverflowLong", String.class);
        method.setAccessible(true);

        try {
            method.invoke(parserMinimalBase, numDesc);
        } catch (Exception e) {
            throw new Exception(e.getCause());
        }

        // Verify that _reportError was called with the expected formatted message
        // Note: _longIntegerDesc is a protected method in the same class, 
        // we expect the output to contain the boundaries.
        String expectedPart1 = "Numeric value";
        String expectedPart2 = "out of range of long";
        String expectedPart3 = String.valueOf(Long.MIN_VALUE);
        String expectedPart4 = String.valueOf(Long.MAX_VALUE);

        // Since we can't easily predict exactly what _longIntegerDesc returns without knowing its implementation details,
        // we verify that _reportError was called with a string containing the key components.
        verify(parserMinimalBase)._reportError(org.mockito.ArgumentMatchers.argThat(msg -> 
            msg.contains(expectedPart1) && 
            msg.contains(expectedPart2) && 
            msg.contains(expectedPart3) && 
            msg.contains(expectedPart4)
        ));
    }

