        }

        // Check if it still reports error even with null description
        verify(parserMinimalBase)._reportError(org.mockito.ArgumentMatchers.anyString());
    }

    @Test(expected = Exception.class)
    public void testReportOverflowLong_ThrowsExceptionWhenReportErrorFails() throws Exception {
        // Force _reportError to throw an exception to test propagation
        // Using Mockito to stub a protected method on a spy
        doThrow(new JsonParseException(null, "Error"))
            .when(parserMinimalBase)._reportError(anyString());

        Method method = ParserMinimalBase.class.getDeclaredMethod("reportOverflowLong", String.class);
        method.setAccessible(true);

        method.invoke(parserMinimalBase, "test");
    }

